const q = $input.first().json.query || {};
const ok = q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === $env.WEBHOOK_VERIFY_TOKEN;
return [{ json: { body: ok ? q['hub.challenge'] : 'token invalido', statusCode: ok ? 200 : 403 } }];

const out = [];
for (const item of $input.all()) {
  const body = item.json.body || item.json;
  for (const e of (body.entry || [])) {
    for (const ch of (e.changes || [])) {
      const v = ch.value || {};
      const contacto = (v.contacts && v.contacts[0]) || {};
      for (const m of (v.messages || [])) {
        let texto = '';
        let inter_id = '';
        if (m.type === 'text') texto = (m.text && m.text.body) || '';
        else if (m.type === 'interactive') {
          const it = m.interactive || {};
          if (it.type === 'list_reply') inter_id = (it.list_reply && it.list_reply.id) || '';
          else if (it.type === 'button_reply') inter_id = (it.button_reply && it.button_reply.id) || '';
        }
        out.push({ json: {
          wa_id: m.from,
          nombre: (contacto.profile && contacto.profile.name) || '',
          tipo: m.type,
          texto,
          inter_id,
          message_id: m.id
        }});
      }
    }
  }
}
return out;

const CAT_LABEL = { deportivas: 'Deportivas', casuales: 'Casuales', urbanas: 'Urbanas' };
const CAT_ORDER = ['deportivas', 'casuales', 'urbanas'];

function fmtPrecio(n) {
  return '$' + String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
}
function unwrap(v) {
  if (v == null) return null;
  if ('integerValue' in v) return parseInt(v.integerValue, 10);
  if ('doubleValue' in v) return v.doubleValue;
  if ('booleanValue' in v) return v.booleanValue;
  if ('stringValue' in v) return v.stringValue;
  if ('arrayValue' in v) return (v.arrayValue.values || []).map(unwrap);
  return null;
}
function parseCatalogo(fsJson) {
  const docs = (fsJson.documents || []);
  const items = docs.map((d) => {
    const f = d.fields || {}; const o = {};
    for (const k in f) o[k] = unwrap(f[k]);
    return o;
  }).filter((o) => o.activo !== false);
  items.sort((a, b) => (a.orden || 999) - (b.orden || 999));
  return items;
}

function listaCategorias(to, catalogo, bodyTexto) {
  const counts = {};
  for (const p of catalogo) counts[p.cat] = (counts[p.cat] || 0) + 1;
  const rows = CAT_ORDER.filter((c) => counts[c]).map((c) => ({
    id: 'cat:' + c, title: CAT_LABEL[c], description: counts[c] + ' modelos disponibles'
  }));
  return { messaging_product: 'whatsapp', to, type: 'interactive', interactive: {
    type: 'list',
    header: { type: 'text', text: 'VarMan Crew 👟' },
    body: { text: (bodyTexto || '¡Hola! Bienvenido a *VarMan Crew*. Estos son nuestros estilos. ¿Cuál quieres ver?').slice(0, 1024) },
    footer: { text: 'Toca «Ver categorías»' },
    action: { button: 'Ver categorías', sections: [{ title: 'Categorías', rows }] }
  }};
}
function listaModelos(to, catalogo, cat) {
  const label = CAT_LABEL[cat] || cat;
  let modelos = catalogo.filter((p) => p.cat === cat);
  const total = modelos.length;
  const hayMas = total > 10;
  modelos = modelos.slice(0, 10);
  const rows = modelos.map((p) => {
    const desc = fmtPrecio(p.precio) + (p.tag ? '  ·  ' + p.tag : '');
    return { id: 'ref:' + p.ref, title: 'Referencia ' + p.ref, description: desc.slice(0, 72) };
  });
  const bodyTxt = hayMas
    ? 'Estos son algunos de nuestros modelos ' + label.toLowerCase() + ' (los primeros 10 de ' + total + '). Toca el que te guste 👇'
    : 'Nuestros modelos ' + label.toLowerCase() + '. Toca el que te guste 👇';
  return { messaging_product: 'whatsapp', to, type: 'interactive', interactive: {
    type: 'list',
    header: { type: 'text', text: 'VarMan Crew · ' + label },
    body: { text: bodyTxt },
    footer: { text: 'Envíos a todo el país' },
    action: { button: 'Ver modelos', sections: [{ title: label, rows }] }
  }};
}
function textoRef(to, catalogo, ref) {
  const p = catalogo.find((x) => x.ref === ref);
  const precio = p ? fmtPrecio(p.precio) : '';
  const texto = p
    ? '¡Buena elección! 🔥\n\nLa *Referencia ' + ref + '* cuesta *' + precio + '*.\n\n¿Qué talla buscas? Escríbeme el número (ej: 40) y te confirmo disponibilidad y el envío. 👟'
    : 'No encontré esa referencia 😅. Escribe *catálogo* para ver los modelos de nuevo.';
  return { messaging_product: 'whatsapp', to, type: 'text', text: { body: texto } };
}
function msjTexto(to, body) {
  return { messaging_product: 'whatsapp', to, type: 'text', text: { body } };
}

// ---- flujo principal ----
const parsed = $('Parsear mensaje').item.json;
const catalogo = parseCatalogo($json);
const to = parsed.wa_id;
const sel = (parsed.inter_id || '').trim();
const mensajes = [];

if (sel.startsWith('cat:')) {
  mensajes.push(listaModelos(to, catalogo, sel.slice(4)));
} else if (sel.startsWith('ref:')) {
  mensajes.push(textoRef(to, catalogo, sel.slice(4)));
} else {
  // Texto libre -> Gemini clasifica la intencion
  const SISTEMA = 'Eres el clasificador de intenciones del bot de WhatsApp de VarMan Crew, una tienda colombiana de zapatos (tenis/sneakers). Analiza el mensaje del cliente y responde SOLO un JSON valido (sin markdown) con esta forma: {"intent":"<una de: saludo|ver_catalogo|pregunta_precio|comprar|hablar_humano|otro>","respuesta":"<respuesta corta y calida en español colombiano, tono vendedor amable, max 2 frases, puede usar 1 emoji>"} Reglas: "saludo": saludos o inicios de conversacion, la respuesta da la bienvenida a VarMan Crew. "ver_catalogo": pide ver zapatos, modelos, catalogo, fotos, o pregunta por un modelo o marca. "pregunta_precio": pregunta precios en general o de una categoria. "comprar": ya quiere comprar o pedir algo concreto. "hablar_humano": pide hablar con una persona, asesor o el dueño. "otro": nada de lo anterior (quejas, envios, etc.), da una respuesta util y ofrece ver el catalogo o hablar con un asesor. Contexto: precios entre $235.000 y $480.000 COP, envios a todo Colombia, pagos por Nequi/Daviplata/Bre-B.';

  let intent = 'saludo';
  let respuesta = '';
  try {
    const r = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://generativelanguage.googleapis.com/v1beta/models/' + ($env.GEMINI_MODEL || 'gemini-2.5-flash-lite') + ':generateContent',
      headers: { 'Content-Type': 'application/json', 'x-goog-api-key': $env.GEMINI_API_KEY },
      body: {
        system_instruction: { parts: [{ text: SISTEMA }] },
        contents: [{ role: 'user', parts: [{ text: (parsed.texto || '').slice(0, 500) }] }],
        generationConfig: { temperature: 0.3, maxOutputTokens: 200, responseMimeType: 'application/json' }
      },
      json: true,
      timeout: 15000
    });
    const out = JSON.parse(r.candidates[0].content.parts[0].text);
    if (out && out.intent) { intent = out.intent; respuesta = out.respuesta || ''; }
  } catch (e) {
    // Gemini caido o sin cupo -> seguimos con el flujo de botones (nunca dejar al cliente sin respuesta)
    intent = 'saludo';
    respuesta = '';
  }

  if (intent === 'hablar_humano') {
    mensajes.push(msjTexto(to, respuesta || '¡Claro! Ya le avisé a nuestro equipo 😊. En un momento te escriben desde el +57 320 225 0619.'));
    const dueno = String($env.OWNER_WHATSAPP || '').replace(/\D/g, '');
    if (dueno && dueno !== to) {
      mensajes.push(msjTexto(dueno, '🔔 *Cliente pide atención humana*\n\nNombre: ' + (parsed.nombre || '(sin nombre)') + '\nWhatsApp: +' + to + '\nÚltimo mensaje: "' + (parsed.texto || '') + '"'));
    }
  } else if (intent === 'otro') {
    mensajes.push(msjTexto(to, respuesta || 'Con gusto te ayudamos 😊. ¿Quieres ver el catálogo? Escribe *catálogo* o dime qué necesitas.'));
  } else if (intent === 'comprar') {
    if (respuesta) mensajes.push(msjTexto(to, respuesta));
    mensajes.push(listaCategorias(to, catalogo, 'Mira nuestro catálogo y toca el modelo que buscas 👇'));
  } else {
    // saludo / ver_catalogo / pregunta_precio -> lista de categorias con el texto de Gemini
    mensajes.push(listaCategorias(to, catalogo, respuesta || undefined));
  }
}

return mensajes.map((m) => ({ json: m }));
